```kotlin
import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val m = scanner.nextInt()

    if (n > m) {
        println(0)
        return
    }
    if (n == m) {
        println(1)
        return
    }

    val a = IntArray(m)
    for (i in 0 until m) {
        a[i] = scanner.nextInt()
    }
    a.sort()

    val b = mutableListOf<Int>()
    var c = 1
    var y = 0
    for (i in 0 until m - 1) {
        if (a[i] == a[i + 1]) {
            c++
            y = 1
        } else {
            b.add(c)
            c = 1
            y = 0
        }
    }
    if (y == 1) {
        b.add(c)
    }
    b.sort()

    var x = 0
    for (i in 1..101) {
        var s = 0
        for (cnt in b) {
            s += cnt / i
        }
        if (s >= n) {
            x = i
        }
    }
    println(x)
}
```

